describe('Password Confirmation Mismatch Error', () => {
  beforeEach(() => {
    cy.visit('/registration');
  });

  it('should display password mismatch error when confirmation password does not match', () => {
    cy.get('[data-testid="password-input"]').type('Password123!');
    cy.get('[data-testid="confirm-password-input"]').type('Password123');
    cy.get('[data-testid="password-input"]').type('DifferentPassword!');
    cy.get('[data-testid="confirm-password-input"]').type('Password123');
    cy.get('[data-testid="submit-button"]').click();

    cy.get('[data-testid="password-mismatch-error"]')
      .should('be.visible')
      .should('contain', 'Passwords and confirmation passwords do not match');
    cy.get('[data-testid="form"]').should('not.have.class', 'success');
  });

  it('should not display error when passwords match', () => {
    cy.get('[data-testid="password-input"]').type('SecurePass123!');
    cy.get('[data-testid="confirm-password-input"]').type('SecurePass123!');
    cy.get('[data-testid="submit-button"]').click();

    cy.get('[data-testid="password-mismatch-error"]').should('not.exist');
    cy.get('[data-testid="form"]').should('have.class', 'success');
    cy.get('[data-testid="success-message"]').should('be.visible');
  });
});
